import { describe, expect, it } from "vitest";

import { dedupeCourses } from "../src/dedupe";
import { courseVersions } from "../src/fixtures";
import { RawCourseVersion } from "../src/types";

const key = (c: RawCourseVersion) => `${c.courseId}|${c.subject}|${c.number}`;

const byKey = (courses: RawCourseVersion[]) => {
  const map = new Map<string, RawCourseVersion>();
  for (const c of courses) {
    if (map.has(key(c))) {
      throw new Error(`dedupeCourses returned more than one row for ${key(c)}`);
    }
    map.set(key(c), c);
  }
  return map;
};

describe("dedupeCourses", () => {
  it("passes through courses with no colliding version untouched", () => {
    const result = byKey(dedupeCourses(courseVersions));

    expect(result.get("10001|COMPSCI|61A")?.status).toBe("ACTIVE");
    expect(result.get("10002|COMPSCI|61B")?.status).toBe("ACTIVE");
  });

  it("collapses ACTIVE + FUTURE with the same subject/number to the ACTIVE row", () => {
    const result = byKey(dedupeCourses(courseVersions));

    const math1a = result.get("20001|MATH|1A");
    expect(math1a).toBeDefined();
    expect(math1a?.status).toBe("ACTIVE");
    expect(math1a?.title).toBe("Calculus");
  });

  it("does NOT collapse a genuine renumbering (different subject/number under the same courseId)", () => {
    const result = byKey(dedupeCourses(courseVersions));

    // Both the current ("ECON 1") and the upcoming ("ECON 1A") numbering
    // must survive as separate rows -- collapsing by courseId alone would
    // silently drop one of them.
    const econActive = result.get("20002|ECON|1");
    const econFuture = result.get("20002|ECON|1A");

    expect(econActive).toBeDefined();
    expect(econActive?.status).toBe("ACTIVE");
    expect(econFuture).toBeDefined();
    expect(econFuture?.status).toBe("FUTURE");
  });

  it("keeps a FUTURE-only course (no ACTIVE version exists yet)", () => {
    const result = byKey(dedupeCourses(courseVersions));

    const stat134 = result.get("30001|STAT|134");
    expect(stat134).toBeDefined();
    expect(stat134?.status).toBe("FUTURE");
  });

  it("deterministically picks one row when duplicate FUTURE records collide (data error case)", () => {
    const result = byKey(dedupeCourses(courseVersions));

    // Two FUTURE|PHYSICS|137A rows exist in the fixture with different
    // fromDates ("2026-01-15" and "2026-06-01"). Exactly one must survive,
    // and it must be the most recently effective one.
    const physics = result.get("40001|PHYSICS|137A");
    expect(physics).toBeDefined();
    expect(physics?.fromDate).toBe("2026-06-01");
  });

  it("produces exactly one row per distinct (courseId, subject, number)", () => {
    const result = dedupeCourses(courseVersions);
    const keys = result.map(key);
    expect(new Set(keys).size).toBe(keys.length);

    // 9 input records, 2 collisions (MATH|1A and PHYSICS|137A) -> 7 distinct keys.
    expect(keys.length).toBe(7);
  });

  it("is order-independent: shuffling the input never changes the output", () => {
    const forward = dedupeCourses(courseVersions);
    const reversed = dedupeCourses([...courseVersions].reverse());

    const sortByKey = (arr: RawCourseVersion[]) =>
      [...arr].sort((a, b) => key(a).localeCompare(key(b)));

    expect(sortByKey(reversed)).toEqual(sortByKey(forward));
  });

  it("is idempotent: running it twice on the same input gives the same result", () => {
    const first = dedupeCourses(courseVersions);
    const second = dedupeCourses(courseVersions);

    expect(second).toEqual(first);
  });

  it("is stable when re-run on its own output (the run after a FUTURE record goes live)", () => {
    // Simulates the boundary case: once a FUTURE record's fromDate arrives,
    // SIS will flip its status to ACTIVE on the next pull. A correct
    // canonical row, re-fed through the same function, must be a fixed
    // point -- re-running dedupe on already-deduped data must not change it.
    const deduped = dedupeCourses(courseVersions);
    const dedupedAgain = dedupeCourses(deduped);

    expect(dedupedAgain).toEqual(deduped);
  });
});
